def split_outside(text: str, sep: str, keyword=False):
    """Split outside quoted BASIC strings."""
    out=[]; start=0; i=0; quoted=False
    n=len(text); L=len(sep)
    while i<=n-L:
        ch=text[i]
        if ch=='"':
            quoted=not quoted; i+=1; continue
        if not quoted and text[i:i+L].upper()==sep.upper():
            out.append(text[start:i]); start=i+L; i=start; continue
        i+=1
    out.append(text[start:])
    return out


def find_keyword(text: str, kw: str):
    quoted=False; i=0; k=kw.upper()
    while i<=len(text)-len(kw):
        if text[i]=='"': quoted=not quoted; i+=1; continue
        if not quoted and text[i:i+len(kw)].upper()==k:
            return i
        i+=1
    return -1


def split_statements(text: str):
    return split_outside(text, ':')


class BasicAdventure:
    def __init__(self, input_func=input, output_func=print):
        self.input_func=input_func
        self.out=output_func
        self.vars={}
        self.stack=[]
        self.part='B'
        self.program=PROGRAM_B
        self.line_numbers=sorted(self.program)
        self.index={n:i for i,n in enumerate(self.line_numbers)}
        self.pc=self.line_numbers[0]
        self.running=True
        self.steps=0

    def default_var(self, name):
        return '' if name.endswith('$') else 0

    def getvar(self, name):
        return self.vars.get(name.upper(), self.default_var(name.upper()))

    def setvar(self, name, value):
        name=name.upper()
        if name.endswith('$'):
            self.vars[name]=str(value)
        else:
            try: self.vars[name]=int(value)
            except Exception: self.vars[name]=0

    def next_line(self, line):
        i=self.index.get(line)
        if i is None or i+1>=len(self.line_numbers): return None
        return self.line_numbers[i+1]

    def jump(self, target):
        target=int(target)
        if target not in self.program:
            raise RuntimeError(f'Linha BASIC inexistente: {target} na parte {self.part}')
        self.pc=target

    def clean_display(self, s):
        # <G57> is the repeated MSX graphic border character.
        s=GRAPH_RE.sub('',s)
        s=s.replace('█████','=====').replace('████','====').replace('█','|')
        # Preserve original wording while making 40-column run-together text readable.
        return s

    def prompt_key(self):
        try:
            s=self.input_func('> ')
        except TypeError:
            s=self.input_func()
        s=(s or '').strip().upper()
        return s[:1]

    def eval_atom(self, expr):
        expr=expr.strip()
        if not expr: return 0
        if expr.upper()=='INKEY$': return self.prompt_key()
        if len(expr)>=2 and expr[0]=='"' and expr[-1]=='"': return expr[1:-1]
        if re.fullmatch(r'&H[0-9A-F]+',expr,re.I): return int(expr[2:],16)
        if re.fullmatch(r'-?\d+',expr): return int(expr)
        if re.fullmatch(r'[A-Za-z][A-Za-z0-9]*\$?',expr): return self.getvar(expr)

        # Minimal safe arithmetic used by this program (e.g. T+1, SD-1).
        names={}
        def repl(m):
            name=m.group(0)
            u=name.upper()
            if u in ('AND','OR','NOT'): return name
            key=f'v{len(names)}'; names[key]=self.getvar(name); return key
        py=re.sub(r'(?<!["A-Za-z0-9_])[A-Za-z][A-Za-z0-9]*\$?',repl,expr)
        try:
            node=ast.parse(py,mode='eval')
            allowed=(ast.Expression,ast.BinOp,ast.UnaryOp,ast.Add,ast.Sub,ast.Mult,ast.Div,ast.FloorDiv,ast.Mod,ast.USub,ast.UAdd,ast.Constant,ast.Name,ast.Load)
            if not all(isinstance(n,allowed) for n in ast.walk(node)): return 0
            return eval(compile(node,'<basic>','eval'),{'__builtins__':{}},names)
        except Exception:
            return 0

    def eval_condition(self, expr):
        expr=expr.strip()
        # BASIC precedence is adequate here if OR is split before AND.
        ors=split_outside(expr,'OR')
        if len(ors)>1: return any(self.eval_condition(x) for x in ors)
        ands=split_outside(expr,'AND')
        if len(ands)>1: return all(self.eval_condition(x) for x in ands)
        if expr.upper().startswith('NOT'):
            return not self.eval_condition(expr[3:])
        quoted=False
        for op in ('<>','>=','<=','>','<','='):
            i=0; quoted=False
            while i<=len(expr)-len(op):
                if expr[i]=='"': quoted=not quoted; i+=1; continue
                if not quoted and expr[i:i+len(op)]==op:
                    a=self.eval_atom(expr[:i]); b=self.eval_atom(expr[i+len(op):])
                    return {'<>':a!=b,'>=':a>=b,'<=':a<=b,'>':a>b,'<':a<b,'=':a==b}[op]
                i+=1
        return bool(self.eval_atom(expr))

    def print_stmt(self, body):
        body=body.strip()
        if not body:
            self.out(''); return
        no_nl=body.endswith(';')
        if no_nl: body=body[:-1]
        # SPC(n)
        body=re.sub(r'SPC\(\s*\d+\s*\)',' ',body,flags=re.I)
        pieces=[]; i=0
        while i<len(body):
            if body[i]=='"':
                j=i+1
                while j<len(body) and body[j]!='"': j+=1
                pieces.append(body[i+1:j]); i=j+1
            elif body[i] in ';,': i+=1
            else:
                j=i
                while j<len(body) and body[j] not in ';,"': j+=1
                token=body[i:j].strip()
                if token:
                    val=self.eval_atom(token)
                    pieces.append(str(val) if val!=0 or token.endswith('$') else (token if not re.fullmatch(r'[A-Za-z][A-Za-z0-9]*\$?',token) else '0'))
                i=j
        text=self.clean_display(''.join(pieces))
        if no_nl:
            print(text,end='',flush=True)
        else:
            self.out(text)

    def execute_if(self, text):
        # text starts with IF and consumes the remainder of the BASIC line.
        body=text[2:]
        p=find_keyword(body,'THEN')
        if p<0: return None
        cond=body[:p]
        branches=body[p+4:]
        e=find_keyword(branches,'ELSE')
        if e>=0:
            yes=branches[:e]; no=branches[e+4:]
        else:
            yes=branches; no=''
        chosen=yes if self.eval_condition(cond) else no
        chosen=chosen.strip()
        if not chosen: return None
        if re.fullmatch(r'\d+',chosen):
            return ('jump',int(chosen))
        return self.execute_sequence(chosen)

    def execute_statement(self, stmt):
        s=stmt.strip()
        if not s: return None
        u=s.upper()
        if u.startswith('REM') or u.startswith("'"): return None
        if u.startswith('PRINT'):
            self.print_stmt(s[5:]); return None
        if u.startswith('CLS'):
            self.out('\n'+'='*72); return None
        if u.startswith('LOCATE'): return None
        if u.startswith('POKE'): return None
        if u.startswith('SCREEN') or u.startswith('WIDTH') or u.startswith('KEYOFF') or u.startswith('KEY OFF') or u.startswith('COLOR') or u.startswith('CLEAR') or u.startswith('DEFINT'):
            return None
        if u.startswith('FOR'):
            # These are timing/display loops in the recovered game. One execution is sufficient.
            return None
        if u.startswith('NEXT'): return None
        if u.startswith('GOTO'):
            m=re.search(r'(\d+)',s); return ('jump',int(m.group(1))) if m else None
        if u.startswith('GOSUB'):
            m=re.search(r'(\d+)',s); return ('gosub',int(m.group(1))) if m else None
        if u=='RETURN' or u.startswith('RETURN '): return ('return',None)
        if u=='RUN': return ('run',None)
        if u.startswith('NEW'): return ('new',None)
        if u.startswith('END') or u.startswith('STOP'): return ('end',None)
        if u.startswith('BLOAD'): return None
        # assignment, optional LET
        a=s[3:] if u.startswith('LET') else s
        m=re.match(r'^([A-Za-z][A-Za-z0-9]*\$?)\s*=\s*(.*)$',a)
        if m:
            self.setvar(m.group(1),self.eval_atom(m.group(2)))
            return None
        # Unknown hardware/preservation-only statement: don't invent semantics.
        return None

    def execute_sequence(self, text):
        parts=split_statements(text)
        i=0
        while i<len(parts):
            s=parts[i].strip()
            if s.upper().startswith('IF'):
                # IF owns the remainder of a BASIC physical line.
                return self.execute_if(':'.join(parts[i:]))
            ctl=self.execute_statement(s)
            if ctl: return ctl
            i+=1
        return None

    def switch_to_c(self):
        self.part='C'; self.program=PROGRAM_C; self.line_numbers=sorted(self.program); self.index={n:i for i,n in enumerate(self.line_numbers)}; self.pc=self.line_numbers[0]; self.stack.clear()
        self.out('\n'+'#'*72)
        self.out('# CONTINUACAO RECUPERADA: PLATOONC.ASM')
        self.out('#'*72+'\n')

    def run(self, max_steps=200000):
        self.out('PLATOON - OBA Soft, 1987')
        self.out('Port de preservacao Python a partir do disco MSX original.\n')
        while self.running and self.steps<max_steps:
            self.steps+=1
            line=self.pc
            src=self.program.get(line,'')
            nxt=self.next_line(line)
            ctl=self.execute_sequence(src)
            if ctl:
                kind,val=ctl
                if kind=='jump': self.jump(val); continue
                if kind=='gosub':
                    self.stack.append(nxt); self.jump(val); continue
                if kind=='return':
                    if not self.stack:
                        self.running=False; break
                    self.pc=self.stack.pop(); continue
                if kind=='run':
                    self.vars={}; self.stack=[]; self.pc=self.line_numbers[0]; continue
                if kind=='new':
                    if self.part=='B': self.switch_to_c(); continue
                    self.out('\n[Fim do material presente nesta imagem de disco.]')
                    self.out('O proprio programa solicita carregar uma ultima parte, mas ela nao existe no DSK analisado.')
                    break
                if kind=='end': break
            if nxt is None: break
            self.pc=nxt
        if self.steps>=max_steps:
            raise RuntimeError('Limite de passos excedido; possivel loop no programa recuperado.')


def main():
    try:
        BasicAdventure().run()
    except KeyboardInterrupt:
        print('\nEncerrado.')

if __name__=='__main__':
    main()
